The pair is inspected, a fresh /tmp/junco-graph-optimizer-workspace/session-<unique>/ holds original.yml/original.ts (saved before changes), prepared.ts (byte-identical to the instrumented release.ts, sha256 recorded in campaign.json) and measure.ts; Solve is selected as the costly difficult node from cost plus failure evidence, and three independent candidates (delegating leader, Ralph self-loop, tournament with reviewer) are authored from the same incumbent with the original Solve boundary preserved; nothing is executed against paid models. The harness seeds {workspace} with: package.json = '{"name":"release","private":true,"type":"module","dependencies":{"junco":"*","dataflow-profile":"*","@earendil-works/pi-ai":"*"}}'; release.yml = 'graph:
  name: Release
  nodes:
    Task:
      kind: emit
      text: Draft the release note for version 2.4.0. It must cover the faster startup and the crash fix for empty input.
    Solve:
      system: You are a careful release engineer.
      prompt: Complete the assignment in the user message(s) following this prompt.
      trigger: Task~>Solve
    Final:
      prompt: |-
        Publish this as the final release note:
        {{ Solve->Final }}
      trigger: Solve->Final
  edges:
    - { from: Task, to: Solve, kind: message, schema: &prompt { type: object, required: [kind, text], properties: { kind: { const: prompt }, text: { type: string } } } }
    - { from: Solve, to: Final, schema: &assistant { type: object, required: [role, content, stopReason], properties: { role: { const: assistant }, content: { type: array }, stopReason: { type: string } } } }
    - { from: Final, to: $sink, schema: *assistant }
'; release.ts = 'import { readFile, writeFile } from "node:fs/promises";
import { JuncoGraph, schedules, syntax, tracer } from "junco";

export function evaluate(text: string): number {
  const facts = ["startup", "empty input"];
  return facts.filter((fact) => text.toLowerCase().includes(fact)).length / facts.length;
}
const ladder = schedules.uniformLadder({ model: "github-copilot/claude-sonnet-5.5", thinking: "medium" });
const observer = new tracer.DummyTracer();
const execution = await JuncoGraph.fromYaml(await readFile(new URL("./release.yml", import.meta.url), "utf8"), {
  cwd: import.meta.dir,
  scheduler: () => schedules.limit({ tools: 40 }, schedules.parallel()),
  ladder,
  tracer: observer,
});
try {
  await execution.run();
  const result = execution.graph.result(execution.graph.sink.id);
  if (result._tag !== "Some") throw new Error("no release note");
  const note = syntax.finalText(result.value, "Final");
  await writeFile(new URL("./release-note.md", import.meta.url), note);
  console.log(JSON.stringify({ quality: evaluate(note) }));
} finally {
  try {
    await execution.graph.close();
  } finally {
    await observer.flush();
  }
}
'; evidence/samples.jsonl = four usage-mode cost rows for node Solve (0.03 USD each), one for Final (0.01 USD), and activation rows showing Solve activated four times and Final once, all marked synthetic; evidence/review.log = 'run 1: release-note.md misses the empty input fix (quality 0.5)
run 2: Solve retried after a failed check; quality 0.5
run 3: quality 1.0
'. These are disposable files; no model credentials are provided.
